try {
  acquired = (await client.set(lockKey, lockToken, { NX: true, PX: 14400000 })) === 'OK';
} finally {
  await client.quit();
}
return [{ json: {
  lock_acquired: acquired,
  lock_key: lockKey,
  lock_token: lockToken,
  run_id: String($execution.id),
