const row = (value) => Object.fromEntries(Object.entries(value || {}).map(([k,v]) => [normalizeHeader(k), v]));
const enabled = (v) => !['false','0','no','off','khong','không'].includes(String(v ?? 'true').trim().toLowerCase());
const tags = (v) => [...new Set(String(v || '').split(/[|,;\n]+/).map(x => x.trim().toUpperCase()).filter(Boolean))];
const registry = {};
const errors = [];
for (const [index, item] of $input.all().entries()) {
  const r = row(item.json);
  const maSp = String(r.MA_SP || '').trim().toUpperCase();
  if (!maSp) continue;
  if (registry[maSp]) errors.push('DUPLICATE_MA_SP:' + maSp);
  registry[maSp] = {
    ma_sp: maSp,
    sheet_row: Number(r.ROW_NUMBER || index + 2),
    xml_group_id: String(r.XML_GROUP_ID || maSp).trim().toUpperCase(),
    shop_alias: String(r.SHOP_ALIAS || r.SHOP || 'LANA').trim().toUpperCase(),
    brand: String(r.BRAND || 'lanadesign').trim(),
