  };
}
return [{ json: { registry, registry_count: Object.keys(registry).length, registry_errors: errors } }];

const crypto = require('crypto');
const source = $input.first().json || {};
const profiles = Array.isArray(source.profiles) ? source.profiles : [];
const run = $('Acquire Ingestion Lock').first().json;
const normalizeText = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').trim().toLowerCase();
const normalizeImageUrl = value => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw);
    url.hash = '';
    url.protocol = url.protocol.toLowerCase();
    url.hostname = url.hostname.toLowerCase();
    for (const key of [...url.searchParams.keys()]) {
      if (/^(utm_|fbclid$|gclid$|_ga$)/i.test(key)) url.searchParams.delete(key);
    }
    url.searchParams.sort();
    return url.toString();
  } catch (_) {
    return raw;
  }
};
const uuid = seed => {
  const chars = crypto.createHash('sha256').update(seed).digest('hex').slice(0, 32).split('');
  chars[12] = '5';
  chars[16] = (parseInt(chars[16], 16) & 3 | 8).toString(16);
  const value = chars.join('');
  return [value.slice(0,8), value.slice(8,12), value.slice(12,16), value.slice(16,20), value.slice(20)].join('-');
};
const jobs = [];
for (const profile of profiles) {
  const reg = profile.reg || {};
