  const material = profile.material_xml || (reg.material_override || []).join(' | ');
  const brand = reg.brand || profile.brand_xml || 'lanadesign';
  const seen = new Set();
  for (let index = 0; index < (profile.images || []).length; index++) {
    const imageUrl = String(profile.images[index] || '').trim();
    const normalizedImageUrl = normalizeImageUrl(imageUrl);
    if (!normalizedImageUrl || seen.has(normalizedImageUrl)) continue;
    seen.add(normalizedImageUrl);
    const pointId = uuid([normalizeText(brand), reg.ma_sp, normalizedImageUrl].join('|'));
    const payload = {
      product_id: reg.ma_sp, ma_sp: reg.ma_sp, aliases: profile.aliases, xml_group_id: profile.group_id,
      shop_alias: reg.shop_alias, brand, rule_type: profile.rule_type, category: profile.category,
      title: profile.title, description, material, material_components: profile.material_components || {},
      color_primary: profile.color_primary || [], color_detail: profile.color_detail || [],
      style_primary: profile.style_primary || '', style_secondary: profile.style_secondary || '',
      style_scores: profile.style_scores || {}, extraction_warnings: profile.extraction_warnings || [],
      extraction_version: source.extraction_version || profile.extraction_version || '',
      product_link: profile.product_link, image_url: imageUrl, normalized_image_url: normalizedImageUrl,
      image_role: (profile.primary_images || []).includes(imageUrl) ? 'PRIMARY' : 'ADDITIONAL', image_sort_order: index + 1,
      images_array: (profile.images || []).slice(0, 8), size_options: profile.sizes, classifications: profile.classifications,
      search_colors: profile.search_colors, search_styles: profile.search_styles, search_materials: profile.search_materials,
      search_silhouettes: profile.search_silhouettes, search_occasions: profile.search_occasions,
      active: reg.active, source: 'WEBSTORE_XML', source_updated_at: profile.xml_updated_at,
      auto_confidence: profile.auto_confidence, review_status: profile.review_status
    };
    const componentText = Object.entries(profile.material_components || {})
      .map(([component, values]) => component + ': ' + (values || []).join(', ')).join('. ');
    const contextual = [
      profile.title, profile.category, ...(profile.color_detail || []), ...(profile.search_colors || []),
      profile.style_primary, profile.style_secondary, componentText, material,
      ...(profile.search_materials || []), ...(profile.search_silhouettes || []), ...(profile.search_occasions || []), description
    ].filter(Boolean).join('. ').slice(0, 1200);
    const sourceHash = crypto.createHash('sha256').update(JSON.stringify({payload, contextual, xml_source_hash: profile.source_hash})).digest('hex');
    jobs.push({json:{
