  run_id: run.run_id, started_at: run.started_at, point_id: '', source_hash: '', payload: {}, image_url: '',
  normalized_image_url: '', job_valid: false, validation_error: 'no_matching_xml_products_or_images',
  delete_requested: false, shard_count: Number(run.shard_count || 1), shard_index: Number(run.shard_index || 0), shard_label: run.shard_label
}}];
return jobs;

