if (!Array.isArray(prediction.textEmbedding) || prediction.textEmbedding.length !== 1408) throw new Error('invalid_product_text_embedding');
const { raw_base64, ...safe } = source;
return [{ json: { ...safe, vector_image_raw: prediction.imageEmbedding, vector_product_text: prediction.textEmbedding } }];

const source = $('Extract Raw Vectors').item.json;
const cutout = $json.predictions?.[0]?.imageEmbedding;
if (!Array.isArray(cutout) || cutout.length !== 1408) throw new Error('invalid_cutout_embedding');
