  id: job.point_id,
  vector: { image_raw: vector_image_raw, image_cutout: cutout, product_text: vector_product_text },
  payload: { ...job.payload, catalog_version: $env.CATALOG_BUILD_VERSION || 'catalog-v2', content_hash: job.source_hash, embedding_model: 'multimodalembedding@001', embedding_dimension: 1408, ingestion_owner: 'P2.3_XML_REGISTRY', ingestion_version: '4.3.0-p2.3-structured-extraction', content_ingested_at: new Date().toISOString() }
} } }];

let job = {};
try { job = $('Loop Over Images').item.json || {}; } catch (_) {}
const input = $input.first().json || {};
const message = String(job.validation_error || input.error?.message || input.message || input.description || 'unknown_ingestion_error').slice(0, 1000);
return [{ json: { status: 'FAILED', point_id: job.point_id || '', ma_sp: job.payload?.ma_sp || '', image_url: job.image_url || '', error: message } }];

const crypto = require('crypto');
const inputItems = $input.all();
const batchContext = $('Select Pending Point Batch').first().json || {};
const failedInBatch = inputItems.filter(item => String(item?.json?.status || '') === 'FAILED').length;
if (Number(batchContext.remaining_point_count || 0) > 0 || failedInBatch > 0) {
  const rows = inputItems.length ? inputItems : [{json:{status:'SKIPPED',error:''}}];
  const reason = failedInBatch > 0 ? 'SKIPPED_BATCH_FAILED' : 'SKIPPED_MORE_PENDING';
  return rows.map((item,index) => index === 0 ? {...item,json:{...(item.json || {}),orphan_cleanup_status:reason,orphan_scanned:0,orphan_owned_scanned:0,orphan_shard_owned_scanned:0,orphan_candidates:0,orphan_deleted:0,orphan_dry_run:true,orphan_cleanup_error:''}} : item);
}
const manifest = $('Prepare Ingestion Jobs').all().map(item => item.json || {});
const run = $('Acquire Ingestion Lock').first().json || {};
const expected = new Set(manifest.filter(job => job.job_valid && !job.delete_requested && job.point_id).map(job => String(job.point_id)));
const shardCount = Math.max(1, Number(run.shard_count || 1));
const shardIndex = Math.max(0, Number(run.shard_index || 0));
const baseUrl = String($env.QDRANT_BASE_URL || 'https://355c0b3c-1e7f-4fa5-9235-72559195dd72.eu-central-1-0.aws.cloud.qdrant.io').replace(/\/$/, '');
const collection = String($env.QDRANT_COLLECTION_INGEST_V2 || 'lana_multimodal_data_v2');
const apiKey = String($env.QDRANT_API_KEY || '');
const enabled = !['false','0','no','off'].includes(String($env.ORPHAN_CLEANUP_ENABLED || 'true').trim().toLowerCase());
const dryRun = ['true','1','yes','on'].includes(String($env.ORPHAN_CLEANUP_DRY_RUN || 'false').trim().toLowerCase());
const pageLimit = Math.min(1000, Math.max(32, Number($env.ORPHAN_SCROLL_PAGE_SIZE || 256)));
const maxPages = Math.min(10000, Math.max(1, Number($env.ORPHAN_SCROLL_MAX_PAGES || 1000)));
const maxDelete = Math.min(10000, Math.max(1, Number($env.ORPHAN_DELETE_MAX || 1000)));
const maxRatio = Math.min(1, Math.max(0.01, Number($env.ORPHAN_DELETE_MAX_RATIO || 0.35)));
let scanned = 0, ownedScanned = 0, shardOwnedScanned = 0, deleted = 0, pages = 0;
let orphanIds = [];
const request = async (options) => {
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try { return await this.helpers.httpRequest(options); }
    catch (error) { lastError = error; if (attempt < 3) await new Promise(resolve => setTimeout(resolve, attempt * 1000)); }
  }
  throw lastError;
};
const finish = (status, error = '') => {
  const meta = { orphan_cleanup_status: status, orphan_scanned: scanned, orphan_owned_scanned: ownedScanned, orphan_shard_owned_scanned: shardOwnedScanned, orphan_candidates: orphanIds.length, orphan_deleted: deleted, orphan_dry_run: dryRun, orphan_cleanup_error: error };
  const rows = inputItems.length ? inputItems : [{ json: { status: 'SKIPPED', error: '' } }];
  return rows.map((item, index) => index === 0 ? { ...item, json: { ...(item.json || {}), ...meta } } : item);
};
try {
  if (!enabled) return finish('DISABLED');
  if (!apiKey) throw new Error('ORPHAN_QDRANT_API_KEY_REQUIRED');
  if (expected.size === 0) throw new Error('ORPHAN_EMPTY_MANIFEST_DELETE_BLOCKED');
  let offset;
  while (true) {
    if (pages >= maxPages) throw new Error('ORPHAN_SCROLL_PAGE_LIMIT_EXCEEDED');
    const body = { limit: pageLimit, with_payload: true, with_vector: false };
    if (offset !== undefined && offset !== null) body.offset = offset;
    const response = await request({ method: 'POST', url: baseUrl + '/collections/' + encodeURIComponent(collection) + '/points/scroll', headers: { 'api-key': apiKey, 'content-type': 'application/json' }, body, json: true, timeout: 30000 });
    const result = response?.result || {};
    const points = Array.isArray(result.points) ? result.points : null;
    if (!points) throw new Error('ORPHAN_SCROLL_RESPONSE_INVALID');
    pages++;
    for (const point of points) {
      scanned++;
      const id = String(point?.id ?? '');
      const payload = point?.payload || {};
      const owned = payload.source === 'WEBSTORE_XML' && (payload.ingestion_owner === 'P2.3_XML_REGISTRY' || payload.ingestion_version === '4.0.0-p2' || payload.ingestion_version === '4.1.0-p2.3' || payload.ingestion_version === '4.2.0-p2.3-orphan-cleanup');
      if (!id || !owned) continue;
