  await client.set(key, JSON.stringify(progress), {EX:604800});
} finally { await client.quit(); }
const progressNote = ['SHARD=' + (progress.shard_index + 1) + '/' + progress.shard_count, 'GROUP=' + progress.run_group, 'PENDING=' + progress.pending_before, 'SELECTED=' + progress.selected, 'REMAINING=' + progress.remaining, 'RETRYABLE=' + retryableFailed, 'FATAL=' + fatalFailed].join(' | ');
const cleanupNote = ['ORPHAN', progress.cleanup_status, 'scanned=' + Number(cleanup.orphan_scanned || 0), 'owned=' + Number(cleanup.orphan_owned_scanned || 0), 'candidates=' + Number(cleanup.orphan_candidates || 0), 'deleted=' + Number(cleanup.orphan_deleted || 0)].join(' | ');
return [{json:{
  RUN_ID: run.run_id, STARTED_AT: run.started_at, FINISHED_AT: progress.finished_at,
  TOTAL: rows.length, SUCCESS: progress.success, SKIPPED: progress.skipped,
  DELETED: progress.deleted, FAILED: failures.length,
  ERROR_SAMPLE: [progressNote, cleanupNote, ...errors].join(' || ').slice(0, 45000)
}}];

const { createClient } = require('redis');
const lock = $('Acquire Ingestion Lock').first().json;
