await client.connect();
let released = 0;
try {
  released = await client.eval("if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end", { keys: [lock.lock_key], arguments: [lock.lock_token] });
} finally { await client.quit(); }
return [{ json: { ...$input.first().json, lock_released: released === 1 } }];

const errorInput = $input.first().json || {};
let lockReleased = false;
try {
  const lock = $('Acquire Ingestion Lock').first().json || {};
  if (lock.lock_key && lock.lock_token) {
    const {createClient} = require('redis');
    const client = createClient({url: $env.REDIS_URL || 'redis://redis:6379'});
    await client.connect();
    try {
      const released = await client.eval("if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end", {keys:[lock.lock_key], arguments:[lock.lock_token]});
