const alertText = ['🚨 LANA / INGESTION FATAL ERROR', 'Error: ' + String(errorInput.error?.message || errorInput.message || errorInput.description || 'UNKNOWN').slice(0, 500), 'Execution: ' + String($execution.id || ''), 'Lock released: ' + String(lockReleased), 'Time: ' + new Date().toISOString()].join('\n');
