  }
  const lines = unicodeText(description).split(/\n|(?<=[.!?;])\s+/).map(v => v.trim()).filter(Boolean);
  for (const line of lines) {
    if (/(^|\W)(màu sắc|màu chủ đạo|gam màu|tông màu|tone màu|phối màu|màu)(\W|$)/i.test(lowerVi(line))) contexts.push(line);
