const apiKey = String($env.QDRANT_API_KEY || '');
if (!apiKey) throw new Error('QDRANT_API_KEY_REQUIRED_FOR_BATCH_SELECTION');
const existing = new Map();
let offset;
let pages = 0;
do {
  if (pages >= 1000) throw new Error('QDRANT_BATCH_SCROLL_LIMIT_EXCEEDED');
  const body = {limit: 1000, with_payload: true, with_vector: false};
  if (offset !== undefined && offset !== null) body.offset = offset;
  const response = await this.helpers.httpRequest({
    method: 'POST', url: baseUrl + '/collections/' + encodeURIComponent(collection) + '/points/scroll',
