const owned = jobs.filter(job => job.job_valid && job.point_id && belongsToShard(job.point_id));
const pending = owned.filter(job => job.delete_requested ? existing.has(String(job.point_id)) : existing.get(String(job.point_id)) !== String(job.source_hash || ''))
  .sort((left, right) => String(left.payload?.ma_sp || '').localeCompare(String(right.payload?.ma_sp || '')) || Number(left.payload?.image_sort_order || 0) - Number(right.payload?.image_sort_order || 0) || String(left.point_id).localeCompare(String(right.point_id)));
