const meta = {
  batch_mode: true, point_batch_size: batchSize, pending_point_count: pending.length,
  batch_selected_point_count: selected.length, remaining_point_count: Math.max(0, pending.length - selected.length),
  qdrant_existing_point_count: existing.size, qdrant_scroll_pages: pages,
  shard_count: shardCount, shard_index: shardIndex, shard_label: run.shard_label
};
if (!selected.length) return [{json:{
  ...meta, run_id: run.run_id, started_at: run.started_at, point_id: '', source_hash: '', payload: {}, image_url: '',
  normalized_image_url: '', job_valid: true, validation_error: '', delete_requested: false,
  should_process: false, no_pending_work: true
}}];
return selected.map(job => ({json:{
